package br.edu.scoa.academico.aplicacao.matriculas;
import br.edu.scoa.academico.aplicacao.identidade.*;import br.edu.scoa.academico.dominio.matriculas.*;import java.time.*;import java.util.*;
public final class GestaoMatriculas {private final ServicoIdentidade identidade;private final Sessao sessao;private final RepositorioMatriculas repositorio;private final Clock relogio;public GestaoMatriculas(ServicoIdentidade i,Sessao s,RepositorioMatriculas r,Clock c){identidade=i;sessao=s;repositorio=r;relogio=c;}private long autor(){if(!identidade.coordenador(sessao))throw new FalhaIdentidade(FalhaIdentidade.Codigo.NAO_AUTORIZADO);return sessao.usuarioId();}public MatriculaCurso salvar(MatriculaCurso m,UUID op){return repositorio.salvar(m,op,autor(),relogio.instant());}public MatriculaCurso consultarNumero(String n){autor();return repositorio.porNumero(n==null?"":n.strip()).orElseThrow(()->new FalhaMatricula(FalhaMatricula.Codigo.NAO_ENCONTRADO));}public List<MatriculaCurso> porAluno(long alunoId){autor();return repositorio.porAluno(alunoId);}}
